class Room:
    def __init__(self, code: str):
        self.code = code
        self.display_ws: List[WebSocket] = []
        self.mc_ws: List[WebSocket] = []
        self.players: Dict[str, dict] = {}
        self.player_ws: Dict[str, WebSocket] = {}
        self.lobby_ws: List[WebSocket] = []
        self.faces: List[dict] = [dict(f) for f in DEFAULT_FACES]
        self.current_game: str = "lobby"
        self.show_ranking: bool = False
        self.show_qr: bool = False
        self.rush_dirty: bool = False
        self.quizzes: List[dict] = [dict(q) for q in DEFAULT_QUIZZES]
        self.card_quizzes: Dict[str, dict] = {}
        self.balances: List[dict] = [dict(b) for b in DEFAULT_BALANCES]
        self.chosungs: List[dict] = [dict(c) for c in DEFAULT_CHOSUNGS]
        self.game_state: dict = {}
        self.bg_tasks: List[asyncio.Task] = []

    def cancel_tasks(self):
        for t in self.bg_tasks:
            if not t.done():
                t.cancel()
        self.bg_tasks.clear()

    def taken_face_ids(self, exclude_pid: Optional[str] = None) -> Dict[str, str]:
        taken = {}
        for pid, p in self.players.items():
            if pid == exclude_pid:
                continue
            fid = p.get("face_id")
            if fid and not fid.startswith("emoji_"):
                taken[fid] = p["name"]
        return taken

    def get_public_players(self):
        return sorted(
            [
                {
                    "id": p["id"],
                    "name": p["name"],
                    "concept": p.get("concept", ""),
                    "face_id": p.get("face_id"),
                    "emoji": p.get("emoji", "🙂"),
                    "outfit": p.get("outfit", "suit"),
                    "hat": p.get("hat", "none"),
                    "item": p.get("item", "none"),
                    "shoes": p.get("shoes", "default"),
                    "score": p["score"],
                    "is_bot": p.get("is_bot", False),
                    "connected": p.get("connected", True),
                }
                for p in self.players.values()
            ],
            key=lambda x: (-x["score"], x["name"]),
        )

    def get_lowest_score_order(self) -> List[str]:
        return [
            p["id"]
            for p in sorted(self.players.values(), key=lambda x: (x["score"], x["name"]))
        ]

    def get_quiz_for_card(self, card_name: str, fallback_idx: int) -> dict:
        if card_name in self.card_quizzes:
            return self.card_quizzes[card_name]
        if self.quizzes:
            q = dict(self.quizzes[fallback_idx % len(self.quizzes)])
            if card_name != "랜덤":
                q["card_tag"] = card_name
            return q
        return {"q": f"{card_name}님 관련 TMI 문제입니다!", "a": "O", "exp": "정답은 O 입니다!"}

    def snapshot(self):
        return {
            "type": "state",
            "room": self.code,
            "current_game": self.current_game,
            "show_ranking": self.show_ranking,
            "show_qr": self.show_qr,
            "quiz_cards": QUIZ_CARDS,
            "studio_count": len(self.lobby_ws),
            "total_connected": len(self.players) + len(self.lobby_ws),
            "players": self.get_public_players(),
            "faces": [{"id": f["id"], "label": f["label"], "img": f["img"]} for f in self.faces],
            "taken_faces": self.taken_face_ids(),
            "game_state": self.game_state,
            "quizzes": self.quizzes,
            "balances": self.balances,
            "chosungs": self.chosungs,
        }

    async def send_to_displays(self, payload: dict):
        text = json.dumps(payload, ensure_ascii=False)
        dead_d = []
        for ws in list(self.display_ws):
            try:
                await ws.send_text(text)
            except Exception:
                dead_d.append(ws)
        for ws in dead_d:
            if ws in self.display_ws:
                self.display_ws.remove(ws)

    async def broadcast(self, payload: Optional[dict] = None):
        data = payload if payload is not None else self.snapshot()
        text = json.dumps(data, ensure_ascii=False)

        dead_d = []
        for ws in list(self.display_ws):
            try:
                await ws.send_text(text)
            except Exception:
                dead_d.append(ws)
        for ws in dead_d:
            if ws in self.display_ws:
                self.display_ws.remove(ws)

        dead_m = []
        for ws in list(self.mc_ws):
            try:
                await ws.send_text(text)
            except Exception:
                dead_m.append(ws)
        for ws in dead_m:
            if ws in self.mc_ws:
                self.mc_ws.remove(ws)

        dead = []
        for pid, ws in list(self.player_ws.items()):
            try:
                await ws.send_text(text)
            except Exception:
                dead.append(pid)
        for pid in dead:
            self.player_ws.pop(pid, None)
            if pid in self.players:
                self.players[pid]["connected"] = False

        dead_lobby = []
        for ws in list(self.lobby_ws):
            try:
                await ws.send_text(text)
            except Exception:
                dead_lobby.append(ws)
        for ws in dead_lobby:
            if ws in self.lobby_ws:
                self.lobby_ws.remove(ws)


rooms: Dict[str, Room] = {}


def generate_room_code() -> str:
    chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    for _ in range(100):
        code = "".join(random.choices(chars, k=4))
        if code not in rooms:
            return code
    return "".join(random.choices(chars, k=5))


@app.get("/", response_class=HTMLResponse)
async def serve_index():
    with open("index.html", "r", encoding="utf-8") as f:
        return HTMLResponse(f.read())


@app.get("/health")
async def health():
    return {"status": "ok", "rooms": len(rooms)}


@app.get("/api/qr")
async def get_qr(data: str = Query(..., min_length=1, max_length=500)):
    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        box_size=10,
        border=2,
    )
    qr.add_data(data)
    qr.make(fit=True)
    img = qr.make_image(image_factory=qrcode.image.svg.SvgPathImage)
    buf = io.BytesIO()
    img.save(buf)
    return Response(content=buf.getvalue(), media_type="image/svg+xml")


# ==================== BOT LOOPS ====================
async def run_bot_fashion(room: Room):
    try:
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        all_ids = list(room.players.keys())
        for bid in bot_ids:
            await asyncio.sleep(random.uniform(0.4, 1.5))
            if room.current_game != "fashion" or room.game_state.get("phase") != "voting":
                return
            others = [pid for pid in all_ids if pid != bid]
            if others:
                room.game_state["votes"][bid] = random.choice(others)
                await room.broadcast()
    except asyncio.CancelledError:
        pass


async def run_bot_stop777(room: Room, start_ts: float):
    try:
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        async def single_bot(bid):
            target = max(3.5, random.gauss(7.77, 0.85))
            delay = (start_ts + target) - time.time()
            if delay > 0:
                await asyncio.sleep(delay)
            if room.current_game == "stop777" and room.game_state.get("phase") == "running":
                if bid not in room.game_state["results"]:
                    elapsed = round(target, 2)
                    room.game_state["results"][bid] = {
                        "time": elapsed,
                        "diff": round(abs(elapsed - 7.77), 2),
                    }
                    await room.broadcast()
        await asyncio.gather(*(single_bot(b) for b in bot_ids))
    except asyncio.CancelledError:
        pass


async def run_bomb_loop(room: Room, duration: float):
    try:
        end_ts = time.time() + duration
        room.game_state["end_ts"] = end_ts
        while time.time() < end_ts:
            if room.current_game != "bomb" or room.game_state.get("phase") != "running":
                return
            now = time.time()
            bombs = room.game_state.get("bombs", [])
            order = room.game_state.get("order", [])
            changed = False
            for b in bombs:
                holder = b.get("holder")
                if holder and room.players.get(holder, {}).get("is_bot"):
                    if now >= b.get("bot_pass_at", 0):
                        busy = {x["holder"] for x in bombs}
                        free_others = [pid for pid in order if pid != holder and pid not in busy]
                        others = free_others if free_others else [pid for pid in order if pid != holder]
                        if others:
                            nxt = random.choice(others)
                            b["holder"] = nxt
                            b["last_pass_ts"] = now
                            b["bot_pass_at"] = now + random.uniform(0.7, 1.45)
                            room.game_state["pass_count"] = room.game_state.get("pass_count", 0) + 1
                            changed = True
            if changed:
                await room.broadcast()
            await asyncio.sleep(0.15)

        if room.current_game == "bomb" and room.game_state.get("phase") == "running":
            bombs = room.game_state.get("bombs", [])
            losers = []
            for b in bombs:
                if b.get("holder") and b["holder"] not in losers:
                    losers.append(b["holder"])
            room.game_state["phase"] = "exploded"
            room.game_state["losers"] = losers
            survivors = []
            for pid in room.game_state.get("order", []):
                if pid not in losers and pid in room.players:
                    room.players[pid]["score"] += 50
                    survivors.append(pid)
            room.game_state["survivors"] = survivors
            await room.broadcast()
    except asyncio.CancelledError:
        pass


async def run_rhythm_loop(room: Room, duration: float = 38.0):
    try:
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        start = time.time()
        while time.time() - start < duration:
            if room.current_game != "rhythm" or room.game_state.get("phase") != "running":
                return
            await asyncio.sleep(0.8)
            elapsed = time.time() - start
            for bid in bot_ids:
                skill = room.game_state["bot_skills"].get(bid, 1.0)
                inc = int(random.uniform(60, 140) * skill * (1 + elapsed / 40.0))
                cur = room.game_state["scores"].get(bid, {"score": 0, "combo": 0, "perfect": 0})
                cur["score"] += inc
                cur["combo"] = random.randint(3, 25)
                cur["perfect"] += random.randint(1, 3)
                room.game_state["scores"][bid] = cur
            await room.broadcast()

        if room.current_game == "rhythm" and room.game_state.get("phase") == "running":
            await finish_rhythm(room)
    except asyncio.CancelledError:
        pass


async def finish_rhythm(room: Room):
    room.game_state["phase"] = "finished"
    scores = room.game_state.get("scores", {})
    ranked = sorted(
        [(pid, scores.get(pid, {"score": 0})["score"]) for pid in room.players.keys()],
        key=lambda x: -x[1],
    )
    awards = [120, 90, 70, 50, 40]
    awarded = {}
    for idx, (pid, sc) in enumerate(ranked):
        pts = awards[idx] if idx < len(awards) else 25
        if sc == 0 and idx > 0:
            pts = 10
        room.players[pid]["score"] += pts
        awarded[pid] = pts
    room.game_state["awarded"] = awarded
    room.game_state["ranked"] = ranked
    await room.broadcast()


async def run_bot_quiz(room: Room):
    try:
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        for bid in bot_ids:
            await asyncio.sleep(random.uniform(0.4, 1.3))
            if room.current_game != "quiz" or room.game_state.get("phase") != "open":
                return
            room.game_state["choices"][bid] = random.choice(["O", "X"])
            await room.broadcast()
        await asyncio.sleep(random.uniform(1.4, 2.8))
        if room.current_game == "quiz" and room.game_state.get("phase") == "open" and bot_ids:
            b = random.choice(bot_ids)
            room.game_state["choices"][b] = "X" if room.game_state["choices"].get(b) == "O" else "O"
            await room.broadcast()
    except asyncio.CancelledError:
        pass



async def run_rush_loop(room: Room, duration: float = 32.0):
    try:
        start = time.time()
        next_toggle = start + random.uniform(2.5, 4.2)
        next_bot_tick = start + 0.28
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        while time.time() - start < duration:
            if room.current_game != "rush" or room.game_state.get("phase") != "running":
                return
            now = time.time()
            changed = room.rush_dirty
            room.rush_dirty = False

            if now >= next_toggle:
                cur_light = room.game_state.get("light", "green")
                if cur_light == "green":
                    room.game_state["light"] = "red"
                    room.game_state["light_changed_ts"] = now
                    next_toggle = now + random.uniform(1.6, 2.5)
                else:
                    room.game_state["light"] = "green"
                    room.game_state["light_changed_ts"] = now
                    next_toggle = now + random.uniform(2.4, 4.0)
                changed = True

            # Bot movement every ~0.28s
            if now >= next_bot_tick:
                next_bot_tick = now + 0.28
                for bid in bot_ids:
                    if bid in room.game_state["finished_order"]:
                        continue
                    if room.game_state.get("light") == "green":
                        if random.random() < 0.68:
                            prog = round(room.game_state["progress"].get(bid, 0) + random.uniform(2.2, 4.4), 1)
                            if prog >= 100:
                                prog = 100.0
                                room.game_state["finished_order"].append(bid)
                            room.game_state["progress"][bid] = prog
                            changed = True
                    else:
                        if now - room.game_state.get("light_changed_ts", 0) > 0.35 and random.random() < 0.06:
                            room.game_state["progress"][bid] = max(0, room.game_state["progress"].get(bid, 0) - 18)
                            room.game_state["caught"][bid] = now
                            changed = True

            if len(room.game_state["finished_order"]) >= len(room.players) and len(room.players) > 0:
                await finish_rush(room)
                return

            if changed:
                await room.broadcast()
            await asyncio.sleep(0.10)

        if room.current_game == "rush" and room.game_state.get("phase") == "running":
            await finish_rush(room)
    except asyncio.CancelledError:
        pass


async def finish_rush(room: Room):
    room.game_state["phase"] = "finished"
    finished = room.game_state.get("finished_order", [])
    progress = room.game_state.get("progress", {})
    rest = sorted(
        [pid for pid in room.players.keys() if pid not in finished],
        key=lambda pid: -progress.get(pid, 0),
    )
    ranked = finished + rest
    awards = [120, 90, 70, 50, 35]
    awarded = {}
    for idx, pid in enumerate(ranked):
        pts = awards[idx] if idx < len(awards) else 20
        if pid in room.players:
            room.players[pid]["score"] += pts
            awarded[pid] = pts
    room.game_state["ranked"] = ranked
    room.game_state["awarded"] = awarded
    await room.broadcast()


async def run_bot_balance(room: Room):
    try:
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        for bid in bot_ids:
            await asyncio.sleep(random.uniform(0.35, 1.2))
            if room.current_game != "balance" or room.game_state.get("phase") != "open":
                return
            room.game_state["choices"][bid] = random.choice(["A", "B"])
            await room.broadcast()
    except asyncio.CancelledError:
        pass


async def run_bot_chosung(room: Room, idx: int):
    try:
        bot_ids = [pid for pid, p in room.players.items() if p.get("is_bot")]
        random.shuffle(bot_ids)
        for bid in bot_ids[:3]:
            await asyncio.sleep(random.uniform(3.2, 6.5))
            if room.current_game != "chosung" or room.game_state.get("phase") != "open" or room.game_state.get("index") != idx:
                return
            if bid not in [w["id"] for w in room.game_state["winners"]]:
                rank = len(room.game_state["winners"]) + 1
                pts = 100 if rank == 1 else (70 if rank == 2 else (50 if rank == 3 else 20))
                room.players[bid]["score"] += pts
                room.game_state["winners"].append({"id": bid, "rank": rank, "pts": pts})
                await room.broadcast()
    except asyncio.CancelledError:
        pass


async def run_auto_lock_countdown(room: Room, expected_game: str, seconds: float = 5.0):
    try:
        await asyncio.sleep(seconds)
        if room.current_game == expected_game and room.game_state.get("phase") == "open":
            room.game_state["phase"] = "locked"
            room.game_state.pop("countdown_end_ts", None)
            await room.broadcast()
    except asyncio.CancelledError:
        pass


@app.websocket("/ws")
async def websocket_endpoint(ws: WebSocket):
    await ws.accept()
    role = None
    room: Optional[Room] = None
    player_id: Optional[str] = None

    try:
        while True:
            raw = await ws.receive_text()
            msg = json.loads(raw)
            mtype = msg.get("type")

            if mtype == "ping":
                await ws.send_text(json.dumps({"type": "pong"}))
                continue

            if mtype in ("display_create", "host_create"):
                req_code = (msg.get("room") or "").strip().upper()
                if req_code and req_code in rooms:
                    room = rooms[req_code]
                else:
                    code = generate_room_code()
                    room = Room(code)
                    rooms[code] = room
                if ws not in room.display_ws:
                    room.display_ws.append(ws)
                role = "display"
                await ws.send_text(json.dumps(room.snapshot(), ensure_ascii=False))
                continue

            if mtype == "mc_auth":
                code = (msg.get("room") or "").strip().upper()
                pin = str(msg.get("pin") or "").strip()
                if code not in rooms:
                    await ws.send_text(json.dumps({
                        "type": "mc_auth_fail",
                        "message": "존재하지 않는 방 코드입니다. 전체화면(공유용)의 방 코드를 확인해주세요."
                    }, ensure_ascii=False))
                    continue
                if pin != MC_PIN:
                    await ws.send_text(json.dumps({
                        "type": "mc_auth_fail",
                        "message": "비밀번호가 틀렸습니다! 4자리 숫자를 다시 입력해주세요."
                    }, ensure_ascii=False))
                    continue
                room = rooms[code]
                role = "mc"
                if ws not in room.mc_ws:
                    room.mc_ws.append(ws)
                await ws.send_text(json.dumps({"type": "mc_authed", "room": code}, ensure_ascii=False))
                await ws.send_text(json.dumps(room.snapshot(), ensure_ascii=False))
                continue

            if mtype == "player_preview":
                code = (msg.get("room") or "").strip().upper()
                if code not in rooms:
                    await ws.send_text(json.dumps({"type": "error", "message": "존재하지 않는 방 코드입니다. 사회자 화면의 코드를 확인해주세요."}, ensure_ascii=False))
                    continue
                room = rooms[code]
                role = "preview"
                if ws not in room.lobby_ws:
                    room.lobby_ws.append(ws)
                await room.broadcast()
                continue

            if mtype == "player_join":
                code = (msg.get("room") or "").strip().upper()
                name = (msg.get("name") or "").strip()[:18]
                concept = (msg.get("concept") or "").strip()[:18]
                face_id = msg.get("face_id")
                emoji = msg.get("emoji") or random.choice(FALLBACK_EMOJIS)
                outfit = msg.get("outfit") if msg.get("outfit") in OUTFITS else "none"
                hat = msg.get("hat") if msg.get("hat") in HATS else "none"
                item = msg.get("item") if msg.get("item") in ITEMS else "none"
                shoes = msg.get("shoes") if msg.get("shoes") in SHOES else "default"
                req_pid = msg.get("player_id")

                if code not in rooms:
                    await ws.send_text(json.dumps({"type": "error", "message": "존재하지 않는 방 코드입니다."}, ensure_ascii=False))
                    continue

                room = rooms[code]
                valid_face_ids = {f["id"] for f in room.faces}
                if not face_id or face_id not in valid_face_ids:
                    await ws.send_text(json.dumps({
                        "type": "error",
                        "message": "사진 캐릭터를 선택해야 입장할 수 있습니다!"
                    }, ensure_ascii=False))
                    await ws.send_text(json.dumps(room.snapshot(), ensure_ascii=False))
                    continue

                taken = room.taken_face_ids(exclude_pid=req_pid)
                if face_id in taken:
                    await ws.send_text(json.dumps({
                        "type": "error",
                        "message": f"앗! 그 얼굴은 방금 '{taken[face_id]}'님이 먼저 선택했어요! 다른 얼굴을 골라주세요."
                    }, ensure_ascii=False))
                    await ws.send_text(json.dumps(room.snapshot(), ensure_ascii=False))
                    continue

                role = "player"
                if ws in room.lobby_ws:
                    room.lobby_ws.remove(ws)

                if req_pid and req_pid in room.players:
                    player_id = req_pid
                    p = room.players[player_id]
                    p["connected"] = True
                    if name:
                        p["name"] = name
                    p["concept"] = concept
                    if face_id:
                        p["face_id"] = face_id
                    p["emoji"] = emoji
                    p["outfit"] = outfit
                    p["hat"] = hat
                    p["item"] = item
                    p["shoes"] = shoes
                else:
                    if not name:
                        await ws.send_text(json.dumps({"type": "error", "message": "닉네임을 입력해주세요!"}, ensure_ascii=False))
                        continue
                    player_id = "p_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=6))
                    room.players[player_id] = {
                        "id": player_id,
                        "name": name,
                        "concept": concept,
                        "face_id": face_id or "emoji_fallback",
                        "emoji": emoji,
                        "outfit": outfit,
                        "hat": hat,
                        "item": item,
                        "shoes": shoes,
                        "score": 0,
                        "is_bot": False,
                        "connected": True,
                    }

                room.player_ws[player_id] = ws
                await ws.send_text(json.dumps({"type": "joined", "player_id": player_id, "room": code}, ensure_ascii=False))
                await room.broadcast()
                continue

            if not room:
                continue

            # --- MC ACTIONS ---
            if role == "mc":
                if mtype == "upload_faces":
                    new_faces = msg.get("faces", [])
                    replace = msg.get("replace", False)
                    if replace:
                        room.faces = []
                    start_idx = len(room.faces) + 1
                    for i, img_data in enumerate(new_faces[:30]):
                        if isinstance(img_data, str) and img_data.startswith("data:image/"):
                            fid = f"face_u_{int(time.time()*1000)}_{i}"
                            room.faces.append({"id": fid, "label": f"얼굴 {start_idx + i}", "img": img_data})
                    await room.broadcast()

                elif mtype == "add_bot":
                    existing = {p["name"] for p in room.players.values()}
                    avail_names = [n for n in BOT_CONCEPTS if n not in existing]
                    bname = avail_names[0] if avail_names else f"익명캐릭{len(room.players)+1}"
                    bid = "bot_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=5))
                    taken = room.taken_face_ids()
                    avail_faces = [f["id"] for f in room.faces if f["id"] not in taken]
                    chosen_face = avail_faces[0] if avail_faces else "emoji_fallback"

                    room.players[bid] = {
                        "id": bid,
                        "name": bname,
                        "concept": "",
                        "face_id": chosen_face,
                        "emoji": random.choice(FALLBACK_EMOJIS),
                        "outfit": random.choice([o for o in OUTFITS if o != "none"]),
                        "hat": random.choice([h for h in HATS if h != "none"]),
                        "item": random.choice([it for it in ITEMS if it != "none"]),
                        "shoes": random.choice(SHOES),
                        "score": 0,
                        "is_bot": True,
                        "connected": True,
                    }
                    await room.broadcast()

                elif mtype == "remove_player":
                    pid = msg.get("player_id")
                    if pid in room.players:
                        room.players.pop(pid, None)
                        room.player_ws.pop(pid, None)
                        await room.broadcast()

                elif mtype == "reset_scores":
                    for p in room.players.values():
                        p["score"] = 0
                    await room.broadcast()

                elif mtype == "switch_game":
                    room.cancel_tasks()
                    target = msg.get("game", "lobby")
                    room.current_game = target
                    if target == "fashion":
                        room.game_state = {"phase": "ready", "votes": {}, "results": [], "awarded": {}}
                    elif target == "stop777":
                        room.game_state = {"phase": "ready", "results": {}, "ordered": [], "revealed_count": 0, "awarded": {}}
                    elif target == "bomb":
                        room.game_state = {
                            "phase": "ready",
                            "order": list(room.players.keys()),
                            "bombs": [],
                            "pass_count": 0,
                            "losers": [],
                            "survivors": [],
                        }
                    elif target == "rhythm":
                        room.game_state = {"phase": "ready", "scores": {}, "duration": 38, "awarded": {}, "ranked": []}
                    elif target == "rush":
                        pids = list(room.players.keys())
                        room.game_state = {
                            "phase": "ready",
                            "light": "green",
                            "lanes": {pid: i for i, pid in enumerate(pids)},
                            "progress": {pid: 0 for pid in pids},
                            "finished_order": [],
                            "caught": {},
                            "ranked": [],
                            "awarded": {},
                        }
                    elif target == "balance":
                        room.game_state = {"phase": "ready", "index": 0, "mode": "majority", "choices": {}, "winners": [], "win_side": None}
                    elif target == "chosung":
                        room.game_state = {"phase": "ready", "index": 0, "winners": []}
                    elif target == "quiz":
                        pick_order = room.get_lowest_score_order()
                        room.game_state = {
                            "phase": "pick",
                            "index": 0,
                            "used_cards": [],
                            "selected_card": None,
                            "current_q": None,
                            "pick_order": pick_order,
                            "pick_turn": 0,
                            "current_picker": pick_order[0] if pick_order else None,
                            "choices": {},
                            "winners": [],
                        }
                    elif target == "podium":
                        room.game_state = {"revealed": 0}
                    else:
                        room.game_state = {}
                    await room.broadcast()

                elif mtype == "fashion_start":
                    room.cancel_tasks()
                    room.game_state = {"phase": "voting", "votes": {}, "results": [], "awarded": {}}
                    await room.broadcast()
                    t = asyncio.create_task(run_bot_fashion(room))
                    room.bg_tasks.append(t)

                elif mtype == "fashion_finish":
                    room.cancel_tasks()
                    votes = room.game_state.get("votes", {})
                    counts = {pid: 0 for pid in room.players.keys()}
                    for voter, target_pid in votes.items():
                        if target_pid in counts:
                            counts[target_pid] += 1
                    ranked = sorted(
                        [{"id": pid, "votes": cnt} for pid, cnt in counts.items()],
                        key=lambda x: (-x["votes"], x["id"]),
                    )
                    awards = [120, 90, 70, 50, 35]
                    awarded = {}
                    for idx, item in enumerate(ranked):
                        pts = awards[idx] if idx < len(awards) else 15
                        if item["votes"] == 0 and idx >= 3:
                            pts = 10
                        room.players[item["id"]]["score"] += pts
                        item["rank"] = idx + 1
                        item["pts"] = pts
                        awarded[item["id"]] = pts
                    room.game_state["phase"] = "revealed"
                    room.game_state["results"] = ranked
                    room.game_state["awarded"] = awarded
                    await room.broadcast()

                elif mtype == "stop777_start":
                    room.cancel_tasks()
                    start_ts = time.time() + 3.0
                    room.game_state = {
                        "phase": "running",
                        "start_ts": start_ts,
                        "server_now": time.time(),
                        "results": {},
                        "ordered": [],
                        "revealed_count": 0,
                        "awarded": {},
                    }
                    await room.broadcast()
                    t = asyncio.create_task(run_bot_stop777(room, start_ts))
                    room.bg_tasks.append(t)

                elif mtype == "stop777_finish":
                    room.cancel_tasks()
                    results = room.game_state.get("results", {})
                    ordered = []
                    for pid in room.players.keys():
                        if pid in results:
                            ordered.append({
                                "id": pid,
                                "time": results[pid]["time"],
                                "diff": results[pid]["diff"],
                                "dnf": False,
                            })
                        else:
                            ordered.append({
                                "id": pid,
                                "time": None,
                                "diff": 99.99,
                                "dnf": True,
                            })
                    ordered.sort(key=lambda x: (-x["diff"], x["id"]))
                    best_first = list(reversed(ordered))
                    awards = [120, 90, 70, 50, 35]
                    awarded = {}
                    for idx, item in enumerate(best_first):
                        pts = 0 if item["dnf"] else (awards[idx] if idx < len(awards) else 20)
                        room.players[item["id"]]["score"] += pts
                        awarded[item["id"]] = pts
                        item["rank"] = idx + 1
                        item["pts"] = pts

                    room.game_state["phase"] = "reveal"
                    room.game_state["ordered"] = ordered
                    room.game_state["revealed_count"] = 0
                    room.game_state["awarded"] = awarded
                    await room.broadcast()

                elif mtype == "stop777_reveal_next":
                    if room.game_state.get("phase") == "reveal":
                        total = len(room.game_state.get("ordered", []))
                        cur = room.game_state.get("revealed_count", 0)
                        if cur < total:
                            room.game_state["revealed_count"] = cur + 1
                            await room.broadcast()

                elif mtype == "stop777_reveal_top5":
                    if room.game_state.get("phase") == "reveal":
                        total = len(room.game_state.get("ordered", []))
                        room.game_state["revealed_count"] = max(0, total - 5)
                        await room.broadcast()

                elif mtype == "stop777_reveal_all":
                    if room.game_state.get("phase") == "reveal":
                        room.game_state["revealed_count"] = len(room.game_state.get("ordered", []))
                        await room.broadcast()

                elif mtype == "bomb_start":
                    room.cancel_tasks()
                    pids = list(room.players.keys())
                    if len(pids) < 2:
                        await ws.send_text(json.dumps({"type": "toast", "message": "최소 2명 이상 참여해야 시작할 수 있습니다!"}, ensure_ascii=False))
                        continue
                    random.shuffle(pids)
                    now = time.time()
                    h1, h2 = pids[0], pids[1]
                    bombs = [
                        {"id": "spot", "doc_type": "Spot", "holder": h1, "last_pass_ts": now, "bot_pass_at": now + random.uniform(0.8, 1.4)},
                        {"id": "bpa", "doc_type": "BPA", "holder": h2, "last_pass_ts": now, "bot_pass_at": now + random.uniform(0.9, 1.6)},
                    ]
                    duration = random.uniform(14.0, 24.0)
                    room.game_state = {
                        "phase": "running",
                        "order": pids,
                        "bombs": bombs,
                        "pass_count": 0,
                        "start_ts": now,
                        "losers": [],
                        "survivors": [],
                    }
                    await room.broadcast()
                    t = asyncio.create_task(run_bomb_loop(room, duration))
                    room.bg_tasks.append(t)

                elif mtype == "rhythm_start":
                    room.cancel_tasks()
                    start_ts = time.time() + 3.0
                    bot_skills = {
                        pid: random.uniform(0.75, 1.35)
                        for pid, p in room.players.items()
                        if p.get("is_bot")
                    }
                    room.game_state = {
                        "phase": "running",
                        "start_ts": start_ts,
                        "server_now": time.time(),
                        "duration": 38,
                        "scores": {pid: {"score": 0, "combo": 0, "perfect": 0} for pid in room.players.keys()},
                        "bot_skills": bot_skills,
                        "awarded": {},
                        "ranked": [],
                    }
                    await room.broadcast()
                    t = asyncio.create_task(run_rhythm_loop(room, 41.0))
                    room.bg_tasks.append(t)

                elif mtype == "rhythm_stop":
                    room.cancel_tasks()
                    if room.game_state.get("phase") == "running":
                        await finish_rhythm(room)

                elif mtype == "quiz_open":
                    room.cancel_tasks()
                    idx = msg.get("index", room.game_state.get("index", 0))
                    if idx < 0 or idx >= len(room.quizzes):
                        idx = 0
                    room.game_state = {"phase": "open", "index": idx, "choices": {}, "winners": []}
                    await room.broadcast()
                    t = asyncio.create_task(run_bot_quiz(room))
                    room.bg_tasks.append(t)

                elif mtype == "quiz_lock":
                    room.cancel_tasks()
                    if room.game_state.get("phase") == "open":
                        room.game_state["phase"] = "locked"
                        await room.broadcast()

                elif mtype == "toggle_ranking":
                    if "show" in msg:
                        room.show_ranking = bool(msg.get("show"))
                    else:
                        room.show_ranking = not room.show_ranking
                    await room.broadcast()

                elif mtype == "toggle_qr":
                    if "show" in msg:
                        room.show_qr = bool(msg.get("show"))
                    else:
                        room.show_qr = not room.show_qr
                    await room.broadcast()

                elif mtype == "start_countdown":
                    if room.current_game in ("balance", "quiz") and room.game_state.get("phase") == "open":
                        sec = float(msg.get("seconds", 5.0))
                        room.game_state["countdown_end_ts"] = time.time() + sec
                        room.game_state["server_now"] = time.time()
                        await room.broadcast()
                        t = asyncio.create_task(run_auto_lock_countdown(room, room.current_game, sec))
                        room.bg_tasks.append(t)

                elif mtype == "quiz_pick_card":
                    room.cancel_tasks()
                    card = (msg.get("card") or "").strip()
                    if card in QUIZ_CARDS:
                        used = room.game_state.get("used_cards", [])
                        if card not in used:
                            used.append(card)
                            room.game_state["used_cards"] = used
                            idx = len(used) - 1
                            q_obj = room.get_quiz_for_card(card, idx)
                            room.game_state["phase"] = "open"
                            room.game_state["index"] = idx
                            room.game_state["selected_card"] = card
                            room.game_state["current_q"] = q_obj
                            room.game_state["choices"] = {}
                            room.game_state["winners"] = []
                            await room.broadcast()
                            t = asyncio.create_task(run_bot_quiz(room))
                            room.bg_tasks.append(t)

                elif mtype == "quiz_back_to_pick":
                    room.cancel_tasks()
                    order = room.game_state.get("pick_order") or room.get_lowest_score_order()
                    # Refresh order if players changed
                    valid_order = [pid for pid in order if pid in room.players]
                    for pid in room.get_lowest_score_order():
                        if pid not in valid_order:
                            valid_order.append(pid)
                    next_turn = room.game_state.get("pick_turn", 0) + 1
                    picker = valid_order[next_turn % len(valid_order)] if valid_order else None
                    room.game_state["phase"] = "pick"
                    room.game_state["selected_card"] = None
                    room.game_state["current_q"] = None
                    room.game_state["pick_order"] = valid_order
                    room.game_state["pick_turn"] = next_turn
                    room.game_state["current_picker"] = picker
                    room.game_state["choices"] = {}
                    room.game_state["winners"] = []
                    await room.broadcast()

                elif mtype == "quiz_reveal":
                    room.cancel_tasks()
                    if room.game_state.get("phase") in ("open", "locked"):
                        q_obj = room.game_state.get("current_q") or room.quizzes[room.game_state.get("index", 0) % len(room.quizzes)]
                        ans = q_obj["a"]
                        winners = []
                        for pid, ch in room.game_state.get("choices", {}).items():
                            if ch == ans and pid in room.players:
                                room.players[pid]["score"] += 50
                                winners.append(pid)
                        room.game_state["phase"] = "revealed"
                        room.game_state["winners"] = winners
                        await room.broadcast()

                elif mtype == "quiz_add":
                    q_text = (msg.get("q") or "").strip()
                    a_val = msg.get("a", "O")
                    exp = (msg.get("exp") or f"정답은 {a_val} 입니다!").strip()
                    if q_text and a_val in ("O", "X"):
                        room.quizzes.append({"q": q_text, "a": a_val, "exp": exp})
                        await room.broadcast()

                elif mtype == "quiz_bulk_import":
                    items = msg.get("items", [])
                    replace = bool(msg.get("replace", False))
                    parsed = []
                    card_mapped = {}
                    for it in items[:50]:
                        cname = (it.get("card") or "").strip()
                        qt = (it.get("q") or "").strip()
                        av = (it.get("a") or "").strip().upper()
                        ex = (it.get("exp") or f"정답은 {av} 입니다!").strip()
                        if qt and av in ("O", "X"):
                            obj = {"q": qt, "a": av, "exp": ex}
                            if cname and cname in QUIZ_CARDS:
                                card_mapped[cname] = obj
                            else:
                                parsed.append(obj)
                    if card_mapped:
                        if replace:
                            room.card_quizzes = card_mapped
                        else:
                            room.card_quizzes.update(card_mapped)
                    if parsed:
                        if replace:
                            room.quizzes = parsed
                        else:
                            room.quizzes.extend(parsed)
                    if card_mapped or parsed:
                        await room.broadcast()


                elif mtype == "rush_start":
                    room.cancel_tasks()
                    pids = list(room.players.keys())
                    random.shuffle(pids)
                    room.game_state = {
                        "phase": "running",
                        "light": "green",
                        "light_changed_ts": time.time(),
                        "start_ts": time.time(),
                        "lanes": {pid: i for i, pid in enumerate(pids)},
                        "progress": {pid: 0.0 for pid in pids},
                        "finished_order": [],
                        "caught": {},
                        "ranked": [],
                        "awarded": {},
                    }
                    await room.broadcast()
                    t = asyncio.create_task(run_rush_loop(room, 32.0))
                    room.bg_tasks.append(t)

                elif mtype == "rush_finish":
                    room.cancel_tasks()
                    if room.game_state.get("phase") == "running":
                        await finish_rush(room)

                elif mtype == "balance_open":
                    room.cancel_tasks()
                    idx = msg.get("index", room.game_state.get("index", 0))
                    mode = msg.get("mode", room.game_state.get("mode", "majority"))
                    if idx < 0 or idx >= len(room.balances):
                        idx = 0
                    room.game_state = {"phase": "open", "index": idx, "mode": mode, "choices": {}, "winners": [], "win_side": None}
                    await room.broadcast()
                    t = asyncio.create_task(run_bot_balance(room))
                    room.bg_tasks.append(t)

                elif mtype == "balance_lock":
                    room.cancel_tasks()
                    if room.game_state.get("phase") == "open":
                        room.game_state["phase"] = "locked"
                        await room.broadcast()

                elif mtype == "balance_reveal":
                    room.cancel_tasks()
                    if room.game_state.get("phase") in ("open", "locked"):
                        choices = room.game_state.get("choices", {})
                        a_ids = [pid for pid, c in choices.items() if c == "A" and pid in room.players]
                        b_ids = [pid for pid, c in choices.items() if c == "B" and pid in room.players]
                        mode = room.game_state.get("mode", "majority")
                        if len(a_ids) == len(b_ids):
                            win_side = "TIE"
                            winners = a_ids + b_ids
                        elif mode == "majority":
                            win_side = "A" if len(a_ids) > len(b_ids) else "B"
                            winners = a_ids if win_side == "A" else b_ids
                        else:
                            win_side = "A" if len(a_ids) < len(b_ids) else "B"
                            winners = a_ids if win_side == "A" else b_ids
                        for pid in winners:
                            room.players[pid]["score"] += 50
                        room.game_state["phase"] = "revealed"
                        room.game_state["win_side"] = win_side
                        room.game_state["winners"] = winners
                        await room.broadcast()

                elif mtype == "chosung_open":
                    room.cancel_tasks()
                    idx = msg.get("index", room.game_state.get("index", 0))
                    if idx < 0 or idx >= len(room.chosungs):
                        idx = 0
                    room.game_state = {"phase": "open", "index": idx, "winners": []}
                    await room.broadcast()
                    t = asyncio.create_task(run_bot_chosung(room, idx))
                    room.bg_tasks.append(t)

                elif mtype == "chosung_reveal":
                    room.cancel_tasks()
                    if room.game_state.get("phase") == "open":
                        room.game_state["phase"] = "revealed"
                        await room.broadcast()


                elif mtype == "adjust_score":
                    pid = msg.get("player_id")
                    delta = int(msg.get("delta", 0))
                    if pid in room.players and -500 <= delta <= 500:
                        room.players[pid]["score"] = max(0, room.players[pid]["score"] + delta)
                        await room.broadcast()

                elif mtype == "podium_reveal_next":
                    if room.current_game == "podium":
                        cur = int(room.game_state.get("revealed", 0))
                        if cur < 3:
                            room.game_state["revealed"] = cur + 1
                            await room.broadcast()

                elif mtype == "podium_reveal_all":
                    if room.current_game == "podium":
                        room.game_state["revealed"] = 3
                        await room.broadcast()

                elif mtype == "trigger_confetti":
                    await room.send_to_displays({"type": "confetti"})

            # --- PLAYER ACTIONS ---
            elif role == "player" and player_id:
                if mtype == "fashion_vote":
                    if room.current_game == "fashion" and room.game_state.get("phase") == "voting":
                        target_pid = msg.get("target_id")
                        if target_pid in room.players:
                            if target_pid == player_id and len(room.players) > 1:
                                await ws.send_text(json.dumps({"type": "toast", "message": "본인 캐릭터에는 투표할 수 없어요! 다른 사람을 골라주세요."}, ensure_ascii=False))
                                continue
                            room.game_state["votes"][player_id] = target_pid
                            await room.broadcast()

                elif mtype == "stop777_press":
                    if room.current_game == "stop777" and room.game_state.get("phase") == "running":
                        if player_id not in room.game_state["results"]:
                            elapsed = msg.get("elapsed")
                            if elapsed is None:
                                elapsed = max(0.0, time.time() - room.game_state["start_ts"])
                            elapsed = round(float(elapsed), 2)
                            room.game_state["results"][player_id] = {
                                "time": elapsed,
                                "diff": round(abs(elapsed - 7.77), 2),
                            }
                            await room.broadcast()

                elif mtype == "bomb_pass":
                    if room.current_game == "bomb" and room.game_state.get("phase") == "running":
                        bombs = room.game_state.get("bombs", [])
                        order = room.game_state.get("order", [])
                        now = time.time()
                        passed = False
                        for b in bombs:
                            if b.get("holder") == player_id:
                                if now - b.get("last_pass_ts", 0) < 0.22:
                                    continue
                                busy = {x["holder"] for x in bombs}
                                free_others = [pid for pid in order if pid != player_id and pid not in busy]
                                others = free_others if free_others else [pid for pid in order if pid != player_id]
                                if not others:
                                    continue
                                b["holder"] = random.choice(others)
                                b["last_pass_ts"] = now
                                b["bot_pass_at"] = now + random.uniform(0.7, 1.45)
                                room.game_state["pass_count"] = room.game_state.get("pass_count", 0) + 1
                                passed = True
                                break
                        if passed:
                            await room.broadcast()

                elif mtype == "rhythm_score":
                    if room.current_game == "rhythm" and room.game_state.get("phase") == "running":
                        room.game_state["scores"][player_id] = {
                            "score": int(msg.get("score", 0)),
                            "combo": int(msg.get("combo", 0)),
                            "perfect": int(msg.get("perfect", 0)),
                        }
                        await room.broadcast()

                elif mtype == "quiz_pick_card":
                    if room.current_game == "quiz" and room.game_state.get("phase") == "pick":
                        if room.game_state.get("current_picker") != player_id:
                            await ws.send_text(json.dumps({"type": "toast", "message": "지금은 다른 분의 카드 선택 차례입니다!"}, ensure_ascii=False))
                            continue
                        card = (msg.get("card") or "").strip()
                        used = room.game_state.get("used_cards", [])
                        if card in QUIZ_CARDS and card not in used:
                            room.cancel_tasks()
                            used.append(card)
                            room.game_state["used_cards"] = used
                            idx = len(used) - 1
                            q_obj = room.get_quiz_for_card(card, idx)
                            room.game_state["phase"] = "open"
                            room.game_state["index"] = idx
                            room.game_state["selected_card"] = card
                            room.game_state["current_q"] = q_obj
                            room.game_state["choices"] = {}
                            room.game_state["winners"] = []
                            await room.broadcast()
                            t = asyncio.create_task(run_bot_quiz(room))
                            room.bg_tasks.append(t)

                elif mtype == "quiz_choose":
                    if room.current_game == "quiz" and room.game_state.get("phase") == "open":
                        ch = msg.get("choice")
                        if ch in ("O", "X"):
                            room.game_state["choices"][player_id] = ch
                            await room.broadcast()


                elif mtype == "rush_tap":
                    if room.current_game == "rush" and room.game_state.get("phase") == "running":
                        if player_id in room.game_state.get("finished_order", []):
                            continue
                        light = room.game_state.get("light", "green")
                        now = time.time()
                        # Give 0.35s human reaction grace period when turning red
                        if light == "red" and (now - room.game_state.get("light_changed_ts", 0)) > 0.35:
                            cur = room.game_state["progress"].get(player_id, 0)
                            room.game_state["progress"][player_id] = max(0, cur - 18)
                            room.game_state["caught"][player_id] = now
                            await ws.send_text(json.dumps({"type": "toast", "message": "🚨 이정훈 상무님한테 걸렸다! 강제 야근 (-18m 후퇴!)"}, ensure_ascii=False))
                            room.rush_dirty = True
                        else:
                            cur = round(room.game_state["progress"].get(player_id, 0) + 3.2, 1)
                            if cur >= 100:
                                cur = 100.0
                                room.game_state["finished_order"].append(player_id)
                            room.game_state["progress"][player_id] = cur
                            if len(room.game_state["finished_order"]) >= len(room.players):
                                await finish_rush(room)
                            else:
                                room.rush_dirty = True

                elif mtype == "balance_choose":
                    if room.current_game == "balance" and room.game_state.get("phase") == "open":
                        ch = msg.get("choice")
                        if ch in ("A", "B"):
                            room.game_state["choices"][player_id] = ch
                            await room.broadcast()

                elif mtype == "chosung_answer":
                    if room.current_game == "chosung" and room.game_state.get("phase") == "open":
                        ans_raw = (msg.get("answer") or "").strip().replace(" ", "")
                        idx = room.game_state.get("index", 0)
                        valid_list = [a.replace(" ", "") for a in room.chosungs[idx]["a"]]
                        already = [w["id"] for w in room.game_state.get("winners", [])]
                        if player_id in already:
                            continue
                        if ans_raw in valid_list:
                            rank = len(already) + 1
                            pts = 100 if rank == 1 else (70 if rank == 2 else (50 if rank == 3 else 20))
                            room.players[player_id]["score"] += pts
                            room.game_state["winners"].append({"id": player_id, "rank": rank, "pts": pts})
                            await ws.send_text(json.dumps({"type": "toast", "message": f"🎉 {rank}등 정답! (+{pts}점 획득!)"}, ensure_ascii=False))
                            await room.broadcast()
                        else:
                            await ws.send_text(json.dumps({"type": "toast", "message": "땡! 다시 도전해보세요!"}, ensure_ascii=False))


                elif mtype == "reaction":
                    emoji = msg.get("emoji", "👏")
                    if emoji in ("👏", "😂", "🔥", "😱", "💸", "❤️"):
                        pname = room.players.get(player_id, {}).get("name", "")
                        payload = {"type": "reaction", "emoji": emoji, "name": pname}
                        await room.send_to_displays(payload)

    except WebSocketDisconnect:
        pass
    except Exception:
        pass
    finally:
        if room:
            was_lobby = ws in room.lobby_ws
            if was_lobby:
                room.lobby_ws.remove(ws)
                try:
                    await room.broadcast()
                except Exception:
                    pass
            if ws in room.display_ws:
                room.display_ws.remove(ws)
            if ws in room.mc_ws:
                room.mc_ws.remove(ws)
            elif role == "player" and player_id:
                if room.player_ws.get(player_id) == ws:
                    room.player_ws.pop(player_id, None)
                if player_id in room.players:
                    room.players[player_id]["connected"] = False
                try:
                    await room.broadcast()
                except Exception:
                    pass
